    if got != want:
        halfcases.append((lines, got, want))
res['prec8_and_halfvalue'] = {'explicit_mismatches': half, 'half_cases_mismatch': halfcases[:5], 'n_half_mismatch': len(halfcases)}
res['prec_after'] = getcontext().prec

